435	    const CAPACITY: usize = 512;
436	    const fn push((buf, i): &mut ([u8; CAPACITY], usize), s: &str) {
437	        let mut k = 0;
438	        while k < s.len() && *i < buf.len() {
439	            buf[*i] = s.as_bytes()[k];
440	            k += 1;
441	            *i += 1;
442	        }
443	    }
