446	    push(&mut dest, "failed to compile-time intern string \"");
447	    push(&mut dest, string);
448	    push(&mut dest, "\". ");
449	    push(&mut dest, error.message());
450	    push(&mut dest, ". you can add an exception to ");
451	    push(&mut dest, file!());
452	    push(&mut dest, " to intern longer strings.");
453	
